ROOT=Path(__file__).resolve().parents[3];OUT=Path(__file__).resolve().parent;G=OUT/'fp64_component_gradients'
CODES={0:'person',1:'bicycle',2:'car',3:'motorcycle',5:'bus',6:'train',7:'truck'};TERMS=['cls_pos','cls_neg','box','dfl'];METHODS=['input','v4','C0','C1']

def load(p):return json.loads(p.read_text(encoding='utf-8'))
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(1048576),b''):h.update(b)
 return h.hexdigest()
def save(name,v):
 p=OUT/name
 if p.exists():
  assert load(p)==v, f'Refuse different existing artifact: {p}'
  return
 with p.open('x',encoding='utf-8',newline='\n') as f:json.dump(v,f,ensure_ascii=False,indent=2,allow_nan=False);f.write('\n')
 assert load(p)==v

def csvwrite(name,rows):
 stream=io.StringIO(newline='');w=csv.DictWriter(stream,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows);data=stream.getvalue().encode('utf-8-sig')
 p=OUT/name
 if p.exists():assert p.read_bytes()==data, f'Refuse different existing CSV: {p}'
 else:
  with p.open('xb') as f:f.write(data)
 assert len(list(csv.DictReader(p.open(encoding='utf-8-sig'))))==len(rows)

def fmt(v,n=6):return 'N/A' if v is None else f'{v:.{n}f}' if isinstance(v,(int,float)) else str(v)
def mdtable(headers,rows):return '\n'.join(['| '+' | '.join(map(str,headers))+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(map(str,r))+' |' for r in rows])

